&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;3&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:360,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;singleLevel&amp;quot;}&quot; data-aria-posinset=&quot;43&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Maintain &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;accurate&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt; chemical inventories and &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;establish&lt;/span&gt; &lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;appropriate stock-level&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt; controls.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:60,&amp;quot;335559740&amp;quot;:269}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
